import { defineConfig } from "vite";
import solid from "vite-plugin-solid";

// The dev server binds loopback so a headless browser (and nothing else) can reach it.
// `src/wasm/` is generated by ../scripts/build-ui-wasm.mjs; when it is absent the app
// falls back to its mock facade (src/facade.ts), so dev and build work either way.
export default defineConfig({
  plugins: [solid()],
  server: { host: "127.0.0.1", port: 5187 },
  build: { target: "es2022", outDir: "dist" },
});
